//! Default-head planner and codebook model generated by
//! scripts/build-native-recognition.mjs (Unlicense).
use voice_simulator_core::{decode::Template, inversion::WIDTH, recognition::codebook::Codebook};

const BYTES: &[u8] = include_bytes!("recognition-model.bin");

struct Reader(&'static [u8]);

impl Reader {
    fn take(&mut self, n: usize) -> &'static [u8] {
        let (values, tail) = self.0.split_at(n);
        self.0 = tail;
        values
    }
    fn word(&mut self) -> u32 {
        u32::from_le_bytes(self.take(4).try_into().unwrap())
    }
    fn number(&mut self) -> f64 {
        f64::from_le_bytes(self.take(8).try_into().unwrap())
    }
    fn control(&mut self, len: usize) -> Vec<f64> {
        (0..len)
            .map(|_| f64::from(f32::from_bits(self.word())))
            .collect()
    }
    fn numbers<const N: usize>(&mut self) -> [f64; N] {
        std::array::from_fn(|_| self.number())
    }
}

pub struct Model {
    tree: Vec<u32>,
    key: Vec<f32>,
    envelope: &'static [u8],
    pub shape: Vec<f64>,
    pub grid: [f64; 24],
    pub tract: [[f64; 4]; WIDTH],
    pub defaults: [f64; WIDTH],
    pub thresholds: [f64; 10],
    pub transitions: Vec<f64>,
    pub noise: [[[f64; 6]; 3]; 2],
    pub voicing_time: f64,
    pub fallback_pitch: f64,
    pub symbols: Vec<(&'static str, bool)>,
    pub templates: Vec<Template>,
    pub render_config: Vec<f64>,
    pub pause_frame: Vec<f64>,
    pub phone_frames: Vec<[Vec<f64>; 3]>,
}

impl Model {
    pub fn load() -> Self {
        let mut input = Reader(BYTES);
        let entries = input.word() as usize;
        let phones = input.word() as usize;
        let tree = (0..entries * 4).map(|_| input.word()).collect();
        let key = (0..entries * 6)
            .map(|_| f32::from_bits(input.word()))
            .collect();
        let envelope = input.take(entries * 24);
        let shape = input
            .take(entries * WIDTH)
            .iter()
            .map(|&x| f64::from(x))
            .collect();
        let grid = input.numbers();
        let tract = std::array::from_fn(|_| input.numbers());
        let defaults = input.numbers();
        let thresholds = input.numbers();
        let transitions = (0..phones * (phones + 1)).map(|_| input.number()).collect();
        let noise = std::array::from_fn(|_| std::array::from_fn(|_| input.numbers()));
        let voicing_time = input.number();
        let fallback_pitch = input.number();
        let config_length = input.word() as usize;
        let frame_stride = input.word() as usize;
        let render_config = (0..config_length).map(|_| input.number()).collect();
        let pause_frame = input.control(frame_stride);
        let mut symbols = Vec::with_capacity(phones);
        let mut templates = Vec::with_capacity(phones);
        let mut phone_frames = Vec::with_capacity(phones);
        for _ in 0..phones {
            let length = input.word() as usize;
            let classes = input.word() as u8;
            let cells = input.word();
            let long = input.word() != 0;
            let symbol = std::str::from_utf8(input.take(length)).unwrap();
            let duration = input.number();
            let compared = (0..cells)
                .map(|_| (input.number() as usize, input.number()))
                .collect();
            symbols.push((symbol, long));
            templates.push(Template {
                duration,
                classes,
                compared,
            });
            phone_frames.push(std::array::from_fn(|_| input.control(frame_stride)));
        }
        assert!(input.0.is_empty());
        Self {
            tree,
            key,
            envelope,
            shape,
            grid,
            tract,
            defaults,
            thresholds,
            transitions,
            noise,
            voicing_time,
            fallback_pitch,
            symbols,
            templates,
            render_config,
            pause_frame,
            phone_frames,
        }
    }

    pub fn codebook(&self) -> Codebook<'_> {
        Codebook::new(&self.tree, &self.key, self.envelope).expect("bundled codebook is valid")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_model_tables_are_aligned() {
        let model = Model::load();
        assert!(model.symbols.iter().any(|&(ipa, _)| ipa == "ə"));
        assert!(model.tract.iter().flatten().all(|value| value.is_finite()));
        assert!(model
            .templates
            .iter()
            .all(|template| template.duration > 0.0));
        assert!(model
            .phone_frames
            .iter()
            .flatten()
            .flatten()
            .all(|value| value.is_finite()));
        model.codebook();
    }
}
